export const getExportUrl = (params?: _ExportParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/v1/analytics/export?${stringifiedParams}` : `/api/v1/analytics/export`
}

export const _export = async (params?: _ExportParams, options?: RequestInit): Promise<_exportResponse> => {
  
  return customFetch<_exportResponse>(getExportUrl(params),
  {      
    ...options,
    method: 'GET'
    
    
  }
);}





